/*{
  "DESCRIPTION": "Flickering fire rising from the bottom of the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.9, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.15, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 8.0, "DEFAULT": 3.0 },
    { "NAME": "flicker", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.5 }
  ]
}*/

float hash1(float n) {
  return fract(sin(n * 43758.5453123) * 43758.5453123);
}

float noise1(float x) {
  float i = floor(x);
  float f = fract(x);
  float a = hash1(i);
  float b = hash1(i + 1.0);
  return mix(a, b, smoothstep(0.0, 1.0, f));
}

void main() {
  vec2 uv = isf_FragNormCoord;
  bool isFlat = RENDERSIZE.y < 2.0;

  float t = TIME * speed;

  // pick the "rising" axis: y normally, x when the model is a flat roofline
  float riseCoord = isFlat ? uv.x : uv.y;
  float acrossCoord = isFlat ? 0.0 : uv.x;

  // upward scrolling noise field, sampled along the rise axis
  float travel = riseCoord * scale * 4.0 - t * 3.0;
  float n1 = noise1(travel + acrossCoord * scale * 6.0);
  float n2 = noise1(travel * 2.03 + acrossCoord * scale * 9.0 + 17.3);
  float flame = n1 * 0.65 + n2 * 0.35;

  // flicker: cheap time-based jitter, whole-canvas so it reads on 1px-tall rows
  float flick = noise1(t * 6.0 + acrossCoord * 2.0);
  flame += (flick - 0.5) * flicker * 0.6;

  // fire dies out toward the top, is strongest at the base
  float base = 1.0 - riseCoord;
  float intensity = clamp(flame * (0.4 + 0.9 * base) - 0.15, 0.0, 1.0);
  intensity = smoothstep(0.05, 0.95, intensity);

  vec3 col = mix(colorB.rgb, colorA.rgb, intensity);

  // near-black embers at the very base fade to nothing when flame is weak
  float glow = smoothstep(0.0, 0.25, intensity);
  col *= mix(0.35, 1.0, glow);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Diagonal candy cane stripes scrolling across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 1.0, "MAX": 20.0, "DEFAULT": 6.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.01, "MAX": 0.5, "DEFAULT": 0.08 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  // On very short/flat buffers (rooflines), fold y's contribution
  // into x so the diagonal motion still reads.
  float diag;
  if (RENDERSIZE.y < 2.0) {
    diag = uv.x * scale - TIME * speed * 0.5;
  } else {
    diag = (uv.x + uv.y) * scale - TIME * speed * 0.5;
  }

  float stripe = fract(diag);
  float band = smoothstep(0.5 - sharpness, 0.5 + sharpness, stripe);

  vec3 col = mix(colorA.rgb, colorB.rgb, band);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A smooth glowing wash that fades between the chosen colours",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "softness", "TYPE": "float", "MIN": 0.1, "MAX": 1.0, "DEFAULT": 0.7 }
  ]
}*/
void main() {
  float t = TIME * speed * 0.15;

  float cycle = fract(t);
  float seg = cycle * 3.0;
  float idx = floor(seg);
  float f = fract(seg);

  float edge = mix(0.05, 0.5, softness);
  float m = smoothstep(0.0, edge, f) * smoothstep(1.0, 1.0 - edge, f);
  m = clamp(f / max(edge, 0.001), 0.0, 1.0);
  m = smoothstep(0.0, 1.0, m);

  vec3 fromCol = colorA.rgb;
  vec3 toCol = colorB.rgb;

  if (idx < 0.5) {
    fromCol = colorA.rgb;
    toCol = colorB.rgb;
  } else if (idx < 1.5) {
    fromCol = colorB.rgb;
    toCol = colorC.rgb;
  } else {
    fromCol = colorC.rgb;
    toCol = colorA.rgb;
  }

  vec3 col = mix(fromCol, toCol, m);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Twinkling stars fade in and out at random positions across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.85, 0.3, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 2.0, "MAX": 16.0, "DEFAULT": 8.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.6 }
  ]
}*/

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

void main() {
  vec2 uv = isf_FragNormCoord;

  vec2 cellCoord;
  if (RENDERSIZE.y < 2.0) {
    cellCoord = vec2(uv.x * density, 0.0);
  } else {
    cellCoord = uv * density;
  }

  vec2 cell = floor(cellCoord);
  vec2 f = fract(cellCoord);

  vec3 col = vec3(0.0);

  for (int oy = 0; oy <= 1; oy++) {
    for (int ox = 0; ox <= 1; ox++) {
      vec2 neighbor = vec2(float(ox), float(oy));
      vec2 gid = cell + neighbor;

      float rnd = hash(gid);
      vec2 starPos = neighbor + vec2(hash(gid + 3.7), hash(gid + 9.2)) * 0.6 + 0.2;
      vec2 diff = f - starPos;
      float dist = length(diff);

      float phase = rnd * 6.2831853;
      float twinkleSpeed = 0.5 + rnd * 1.5;
      float twinkle = 0.5 + 0.5 * sin(TIME * speed * twinkleSpeed + phase);
      twinkle = pow(twinkle, mix(1.0, 4.0, sharpness));

      float radius = mix(0.35, 0.12, sharpness);
      float star = smoothstep(radius, 0.0, dist) * twinkle;

      vec3 starColor = mix(colorA.rgb, colorB.rgb, hash(gid + 5.5));
      col += starColor * star;
    }
  }

  col = clamp(col, 0.0, 1.0);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A bright chase of color running along the roofline",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "count", "TYPE": "float", "MIN": 2.0, "MAX": 16.0, "DEFAULT": 8.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.05, "MAX": 0.9, "DEFAULT": 0.35 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  // Drive the chase along x always; if the buffer is tall, fold y in too
  // so the chase still reads as horizontal motion along a roofline.
  float pos = uv.x;
  if (RENDERSIZE.y >= 2.0) {
    pos = uv.x;
  }

  float n = max(count, 1.0);
  float scaled = pos * n - TIME * speed * 2.0;
  float cell = fract(scaled);

  // Sharp pulse within each cell
  float half_w = clamp(sharpness, 0.05, 0.9) * 0.5;
  float d = abs(cell - 0.5);
  float pulse = 1.0 - smoothstep(half_w * 0.5, half_w, d);

  // Alternate base color per cell for a two-tone chase
  float cellIndex = floor(scaled);
  float toggle = mod(cellIndex, 2.0);
  vec3 base = mix(colorA.rgb, colorB.rgb, toggle);

  // Dim background so the chase pops, never fully black
  vec3 bg = mix(colorA.rgb, colorB.rgb, 0.5) * 0.08;

  vec3 col = mix(bg, base, pulse);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Swirling plasma blending three Christmas colours",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 6.0, "DEFAULT": 2.5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  bool flat = RENDERSIZE.y < 2.0;

  float t = TIME * speed;

  vec2 p;
  if (flat) {
    p = vec2(uv.x * scale * 2.0, uv.x * scale * 0.6);
  } else {
    p = uv * scale;
  }

  float swirl = sin(p.x * 2.0 + t) + sin(p.y * 2.0 - t * 0.8);
  float angle = swirl * 0.6;
  float c = cos(angle);
  float s = sin(angle);
  vec2 q = vec2(p.x * c - p.y * s, p.x * s + p.y * c);

  float plasma = sin(q.x * 1.5 + t)
               + sin(q.y * 1.5 - t * 1.2)
               + sin((q.x + q.y) * 1.2 + t * 0.7)
               + sin(length(q) * 1.8 - t * 1.5);

  plasma = plasma * 0.25 * 0.5 + 0.5;

  vec3 col;
  if (plasma < 0.5) {
    col = mix(colorA.rgb, colorB.rgb, smoothstep(0.0, 0.5, plasma));
  } else {
    col = mix(colorB.rgb, colorC.rgb, smoothstep(0.5, 1.0, plasma));
  }

  col = clamp(col * 1.15, 0.0, 1.0);

  gl_FragColor = vec4(col, 1.0);
}

