/*{
  "DESCRIPTION": "A saturated rainbow band sweeps across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 6.0, "DEFAULT": 2.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.6 }
  ]
}*/

vec3 rainbow(float t) {
  float r = abs(fract(t + 0.0 / 3.0) * 6.0 - 3.0) - 1.0;
  float g = abs(fract(t + 2.0 / 3.0) * 6.0 - 3.0) - 1.0;
  float b = abs(fract(t + 1.0 / 3.0) * 6.0 - 3.0) - 1.0;
  return clamp(vec3(r, g, b), 0.0, 1.0);
}

void main() {
  vec2 uv = isf_FragNormCoord;

  float pos = uv.x;
  if (RENDERSIZE.y < 2.0) {
    pos = uv.x;
  } else {
    pos = mix(uv.x, uv.y, 0.0);
  }

  float t = pos * scale - TIME * speed * 0.3;

  vec3 col = rainbow(t);

  float sat = mix(1.0, 2.2, sharpness);
  col = clamp((col - 0.5) * sat + 0.5, 0.0, 1.0);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Everything pulses in unison to a steady beat",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 0.8, 0.2, 1.0] },
    { "NAME": "bpm", "TYPE": "float", "MIN": 40.0, "MAX": 200.0, "DEFAULT": 120.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.05, "MAX": 0.95, "DEFAULT": 0.6 },
    { "NAME": "minBrightness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.15 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  float beatsPerSec = bpm / 60.0;
  float phase = fract(TIME * beatsPerSec);

  float pulseWidth = clamp(1.0 - sharpness, 0.02, 0.98);
  float pulse = 1.0 - smoothstep(0.0, pulseWidth, phase);
  pulse = pulse * pulse;

  float bright = mix(minBrightness, 1.0, pulse);

  float side = step(0.5, uv.x);
  vec3 base = mix(colorA.rgb, colorB.rgb, side);

  vec3 col = base * bright;

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A waving American-style flag of stripes and stars in red white and blue",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.7, 0.05, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.05, 0.1, 0.5, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "waveAmount", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool tall = RENDERSIZE.y >= 2.0;

  // pick the axis that runs "across the flag length" so waving always reads
  vec2 p = tall ? uv : uv.yx;

  float t = TIME * speed;

  // waving distortion: ripples travel along x, displace y
  float wave = sin(p.x * 8.0 + t * 2.5) * 0.03 * waveAmount
             + sin(p.x * 3.0 + t * 1.3) * 0.02 * waveAmount;
  float py = p.y + wave;
  float px = p.x + wave * 0.5;

  // canton (blue star field) occupies top-left ~0.55 x 0.5
  bool inCanton = px < 0.55 && py > 0.5;

  vec3 col;

  if (inCanton) {
    // simple star grid using distance to nearest grid point
    vec2 cuv = vec2(px / 0.55, (py - 0.5) / 0.5);
    vec2 grid = vec2(6.0, 5.0);
    vec2 cell = fract(cuv * grid) - 0.5;
    float d = length(cell);
    float star = step(d, 0.18);
    col = mix(colorC.rgb, colorB.rgb, star);
  } else {
    // 7 stripes, alternating red/white, offset by wave
    float stripeIndex = floor(py * 7.0);
    float stripeFrac = mod(stripeIndex, 2.0);
    col = mix(colorA.rgb, colorB.rgb, stripeFrac);
  }

  // subtle shading from wave to sell the fabric motion
  float shade = 0.9 + 0.1 * sin(p.x * 8.0 + t * 2.5);
  col *= shade;

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Spooky green fog drifting across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.02, 0.15, 0.05, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.2, 0.9, 0.3, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.5, "MAX": 3.0, "DEFAULT": 1.5 },
    { "NAME": "murk", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.4 }
  ]
}*/

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

void main() {
  vec2 uv = isf_FragNormCoord;
  bool flat1D = RENDERSIZE.y < 2.0;

  float t = TIME * speed * 0.15;

  vec2 p;
  if (flat1D) {
    p = vec2(uv.x * density * 4.0 - t * 2.0, t * 0.5);
  } else {
    p = vec2(uv.x * density * 4.0 - t * 2.0, uv.y * density * 2.0 + t * 0.5);
  }

  float n1 = noise(p);
  float n2 = noise(p * 1.7 + vec2(5.2, 1.3) - t);
  float fog = n1 * 0.6 + n2 * 0.4;

  fog = smoothstep(0.2, 0.9, fog);

  float shimmer = 0.5 + 0.5 * sin(TIME * speed * 0.6 + uv.x * 6.0);
  fog = mix(fog, fog * shimmer, murk * 0.3);

  vec3 col = mix(colorA.rgb, colorB.rgb, fog);

  float vign = 1.0 - murk * 0.3 * (1.0 - fog);
  col *= vign;

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A spinning tunnel of colored rings that pulls you inward",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "spin", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "rings", "TYPE": "float", "MIN": 2.0, "MAX": 16.0, "DEFAULT": 8.0 }
  ]
}*/
void main() {
  vec2 res = RENDERSIZE;
  vec2 uv;

  if (res.y < 2.0) {
    // single row of lights: fake the tunnel by mapping x to angle
    // and using time as the "depth" axis so motion still reads along x
    float ang = uv.x;
    uv = isf_FragNormCoord;
    float a = uv.x * 6.2831853;
    float depth = fract(TIME * speed * 0.3);
    float rr = fract(depth * rings + a * 0.5);
    float band = smoothstep(0.0, 0.08, rr) - smoothstep(0.42, 0.5, rr);
    vec3 col = mix(colorA.rgb, colorB.rgb, step(0.5, fract(a / 6.2831853 * 2.0 + depth)));
    col = mix(col, colorC.rgb, band);
    gl_FragColor = vec4(col, 1.0);
    return;
  }

  uv = isf_FragNormCoord * 2.0 - 1.0;
  uv.x *= res.x / max(res.y, 1.0);

  float r = length(uv) + 0.0001;
  float a = atan(uv.y, uv.x);

  // spin the angle over time
  a += TIME * spin;

  // depth coordinate: inverse radius creates the flying-forward feel
  float depth = 1.0 / r - TIME * speed * 2.0;

  float ringPattern = fract(depth * (rings * 0.1));
  float ringMask = smoothstep(0.0, 0.1, ringPattern) - smoothstep(0.5, 0.6, ringPattern);

  // color banding around the angle, shifting with depth for spiral feel
  float colorPhase = fract(a / 6.2831853 * 3.0 + depth * 0.15);
  vec3 baseCol = mix(colorA.rgb, colorB.rgb, step(0.5, colorPhase));

  vec3 col = mix(baseCol * 0.25, colorC.rgb, ringMask);

  // darken toward center a touch less, brighten near mid-tunnel for depth cue
  float vign = smoothstep(1.6, 0.1, r);
  col *= mix(0.6, 1.2, vign);

  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

/*{
  "DESCRIPTION": "Layered ocean waves rolling across the display in blues and whitecaps",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.0, 0.15, 0.5, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 0.6, 0.8, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 6.0, "DEFAULT": 2.5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  // If the buffer is tall (a real 2D grid), drive waves along y and layer with x.
  // If it is a single row (roofline), fold the same motion onto x alone.
  float flat = step(RENDERSIZE.y, 1.5);

  float t = TIME * speed;

  // Coordinate that carries the wave motion: y normally, x when flat.
  float wc = mix(uv.y, uv.x, flat);
  float xc = mix(uv.x, 0.5, flat);

  // Three layered waves of differing frequency/speed for rolling motion.
  float w1 = sin(wc * scale * 6.2831 + xc * 3.0 + t * 1.3);
  float w2 = sin(wc * scale * 10.0 - xc * 2.0 - t * 0.9 + 1.7);
  float w3 = sin(wc * scale * 3.0 + xc * 1.0 + t * 0.5 - 0.8);

  float wave = (w1 * 0.5 + w2 * 0.3 + w3 * 0.2);
  wave = wave * 0.5 + 0.5;

  // Base ocean gradient from deep to lighter blue.
  vec3 ocean = mix(colorA.rgb, colorB.rgb, wave);

  // Whitecap highlight where wave peaks are sharp.
  float crest = smoothstep(0.72, 0.95, wave);
  vec3 col = mix(ocean, colorC.rgb, crest);

  // Subtle horizontal roll shimmer so a flat roofline still reads motion.
  float shimmer = sin(uv.x * 20.0 * scale * 0.2 + t * 2.0) * 0.05;
  col += shimmer * crest;

  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

