/*{
  "DESCRIPTION": "Warm flickering candle glow across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.6, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.15, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "flicker", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  float t = TIME * speed;

  // several offset sine waves make an irregular, non-repeating-feeling flicker
  float n = sin(t * 3.1) * 0.35
          + sin(t * 7.7 + 1.3) * 0.25
          + sin(t * 13.3 + 3.7) * 0.15
          + sin(t * 1.9 + 5.1) * 0.25;
  n = n * 0.5 + 0.5;

  // slow base breathing so it never feels static, layered with the fast flicker
  float breathe = 0.85 + 0.15 * sin(t * 0.6);
  float brightness = mix(1.0, n, flicker) * breathe;
  brightness = clamp(brightness, 0.15, 1.0);

  // subtle warm gradient across the canvas so a roofline still shows variation
  float pos = (RENDERSIZE.y < 2.0) ? uv.x : (uv.x * 0.5 + uv.y * 0.5);
  float mixAmt = clamp(pos * 0.6 + (1.0 - brightness) * 0.8, 0.0, 1.0);

  vec3 col = mix(colorA.rgb, colorB.rgb, mixAmt) * brightness;

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Diagonal candy-cane stripes spin continuously like a barber pole",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "stripes", "TYPE": "float", "MIN": 2.0, "MAX": 16.0, "DEFAULT": 6.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.05, "MAX": 0.5, "DEFAULT": 0.15 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  // If the buffer is short and wide (a roofline), the spiral motion should
  // still read as horizontal travel; otherwise use the usual diagonal.
  float diag;
  if (RENDERSIZE.y < 2.0) {
    diag = uv.x - TIME * speed * 0.5;
  } else {
    diag = uv.x + uv.y - TIME * speed * 0.5;
  }

  float phase = fract(diag * stripes);
  float band = smoothstep(0.5 - sharpness, 0.5 + sharpness, phase)
             - smoothstep(1.0 - sharpness, 1.0 + sharpness, phase)
             + smoothstep(0.0 - sharpness, 0.0 + sharpness, phase) * step(phase, sharpness);

  band = clamp(band, 0.0, 1.0);

  vec3 col = mix(colorB.rgb, colorA.rgb, band);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Rippling rings expand outward like raindrops on a dark surface",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.1, 0.3, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.6, 0.8, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "drops", "TYPE": "long", "MIN": 1, "MAX": 8, "DEFAULT": 5 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.5, "MAX": 6.0, "DEFAULT": 2.5 }
  ]
}*/

float hash1(float n) {
  return fract(sin(n * 127.1) * 43758.5453);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  bool flat1D = RENDERSIZE.y < 2.0;

  vec2 p = uv * 2.0 - 1.0;
  p.x *= max(RENDERSIZE.x / max(RENDERSIZE.y, 1.0), 1.0);

  vec3 col = vec3(0.0);
  float period = 3.0;

  for (int i = 0; i < 8; i++) {
    if (i >= drops) break;
    float fi = float(i);
    float seed = fi * 17.37;

    float cx = hash1(seed) * 2.0 - 1.0;
    float cy = hash1(seed + 3.14) * 2.0 - 1.0;
    vec2 center = flat1D ? vec2(cx, 0.0) : vec2(cx, cy);

    float t = mod(TIME * speed * 0.35 + hash1(seed + 7.0) * period, period);

    float dist;
    if (flat1D) {
      dist = abs(p.x - center.x);
    } else {
      dist = length(p - center);
    }

    float radius = t;
    float ring = abs(dist - radius);
    float width = 0.05 + 0.05 * (t / period);
    float intensity = 1.0 - smoothstep(0.0, width * sharpness, ring);

    float fade = 1.0 - smoothstep(0.0, period, t);
    intensity *= fade;

    vec3 dropColor = mix(colorA.rgb, colorB.rgb, hash1(seed + 1.5));
    col += dropColor * intensity;
  }

  col = clamp(col, 0.0, 1.0);
  vec3 bg = mix(colorA.rgb, colorB.rgb, 0.5) * 0.05;
  col = max(col, bg);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Shifting aurora borealis curtains of colored light",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.4, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 0.4, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.6, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "bands", "TYPE": "float", "MIN": 1.0, "MAX": 6.0, "DEFAULT": 3.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool flat = RENDERSIZE.y < 2.0;

  // pick the axis that gives the most spatial resolution for the wave shape
  float pos = flat ? uv.x : uv.y;
  float along = flat ? uv.y : uv.x;

  float t = TIME * speed * 0.3;

  // build several overlapping shifting waves to fake curtain folds
  float wave1 = sin(along * 6.28318 * bands + t * 2.0) * 0.5;
  float wave2 = sin(along * 6.28318 * bands * 1.7 - t * 1.3 + 1.5) * 0.3;
  float wave3 = sin(along * 6.28318 * bands * 0.6 + t * 0.7) * 0.2;
  float wave = wave1 + wave2 + wave3;

  // vertical (or along-x when flat) falloff of the curtain glow around the wave center
  float dist = abs(pos - 0.5 - wave * 0.35);
  float glow = smoothstep(0.5, 0.0, dist);
  glow = pow(glow, 1.6);

  // color drifts slowly between the three palette colors along the curtain
  float mixer = fract(along * bands * 0.5 + t * 0.15);
  vec3 col;
  if (mixer < 0.5) {
    col = mix(colorA.rgb, colorB.rgb, smoothstep(0.0, 0.5, mixer));
  } else {
    col = mix(colorB.rgb, colorC.rgb, smoothstep(0.5, 1.0, mixer));
  }

  // faint shimmer flicker
  float shimmer = 0.85 + 0.15 * sin(along * 40.0 + t * 5.0);

  vec3 finalColor = col * glow * shimmer;

  // dark sky background with a hint of deep blue-green
  vec3 bg = vec3(0.0, 0.02, 0.05);
  finalColor = max(finalColor, bg * (1.0 - glow));

  gl_FragColor = vec4(finalColor, 1.0);
}

